/* eslint-disable */
/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type AccessRequestInput = {
  fileIds: Array<string | number>;
  reason: string;
};

export type ArrangementInput = {
  description?: string | null | undefined;
  /** Only when creating. */
  numberId?: string | number | null | undefined;
};

export type AuditFilter = {
  /** CREATE, UPDATE, DELETE and so on. */
  action?: string | null | undefined;
  /** Who made the change; only ADMIN sees others' changes. */
  actorId?: string | null | undefined;
  /** One record's changes. */
  entityId?: string | number | null | undefined;
  /** What was changed, e.g. MANUSCRIPT, VERSION or SHARE_LINK. */
  entityType?: string | null | undefined;
  /** Changes from this instant on. */
  from?: string | null | undefined;
  /** Text the summary contains. */
  q?: string | null | undefined;
  /** Changes before this instant. */
  to?: string | null | undefined;
};

export type FileAddInput = {
  comment?: string | null | undefined;
  desk?: string | null | undefined;
  instrumentIds?: Array<string | number> | null | undefined;
  /** With roleId, the role is not guessed: instruments, desk and transposition are as given. */
  roleId?: string | number | null | undefined;
  /** Defaults to the upload's name without its extension. */
  title?: string | null | undefined;
  /** Defaults to the first instrument's default transposition. */
  transposition?: TranspositionInput | null | undefined;
  uploadId: string;
  versionId: string | number;
};

export type FileInput = {
  comment?: string | null | undefined;
  desk?: string | null | undefined;
  /** A part needs at least one. */
  instrumentIds?: Array<string | number> | null | undefined;
  roleId: string | number;
  title: string;
  /** Defaults to the first instrument's default transposition. */
  transposition?: TranspositionInput | null | undefined;
};

export type FileRoleInput = {
  nameEn: string;
  nameSv: string;
};

export type InstrumentGroup =
  | 'BRASS'
  | 'OTHER'
  | 'RHYTHM'
  | 'STRINGS'
  | 'VOICES'
  | 'WOODWIND';

export type InstrumentInput = {
  abbreviations?: Array<string> | null | undefined;
  /** Unchanged when not given; C for new instruments. */
  defaultTransposition?: TranspositionInput | null | undefined;
  group: InstrumentGroup;
  nameEn: string;
  nameSv: string;
};

export type InstrumentationInput = {
  count: number;
  instrumentId: string | number;
};

/** A key to set or filter by; filters match whatever the spelling, so C_SHARP finds D_FLAT. */
export type KeyInput = {
  mode: Mode;
  tonic: Tonic;
};

/**
 * The maintenance jobs: SPEX_REFRESH copies the spex from Spexregister, UPLOAD_CLEANUP removes uploads older than 24
 * hours, FILE_BACKFILL queues files without text or preview for the worker again, RETENTION removes download logs and
 * access requests older than 24 months and users not seen for 36 months.
 */
export type MaintenanceJob =
  | 'FILE_BACKFILL'
  | 'RETENTION'
  | 'SPEX_REFRESH'
  | 'UPLOAD_CLEANUP';

export type ManuscriptInput = {
  authors?: string | null | undefined;
  description?: string | null | undefined;
  /** Only when creating: an original spex. */
  spexId?: string | number | null | undefined;
  /** Defaults to the spex' title. */
  title?: string | null | undefined;
};

export type MaterialKind =
  | 'ARRANGEMENT'
  | 'MANUSCRIPT';

export type Mode =
  | 'MAJOR'
  | 'MINOR';

export type NumberInput = {
  composer?: string | null | undefined;
  lyricist?: string | null | undefined;
  originalSong?: string | null | undefined;
  title: string;
};

/**
 * Narrows parts to some instruments and transpositions: a file matches when it is a part (role Part), carries any of
 * the instruments and is written in any of the pitches; scores and sources are never parts, whatever they carry. An empty
 * list does not narrow.
 */
export type PartFilter = {
  instrumentIds?: Array<string | number> | null | undefined;
  transpositions?: Array<Pitch> | null | undefined;
};

/** The pitch a part is written in, in ASCII: C is concert pitch, B_FLAT is B♭ (Swedish B), B is Swedish H. */
export type Pitch =
  | 'A'
  | 'A_FLAT'
  | 'B'
  | 'B_FLAT'
  | 'C'
  | 'D'
  | 'D_FLAT'
  | 'E'
  | 'E_FLAT'
  | 'F'
  | 'F_SHARP'
  | 'G';

export type ProcessingStatus =
  | 'DONE'
  | 'FAILED'
  /** Waiting for its page count, text and preview. */
  | 'PENDING';

export type SettingsInput = {
  accessRequestRecipients?: Array<string> | null | undefined;
  arrangementRestricted: boolean;
  manuscriptRestricted: boolean;
  maxShareLinkMonths: number;
  maxUploadMb: number;
  welcomeEn?: string | null | undefined;
  welcomeSv?: string | null | undefined;
};

export type ShareLinkInput = {
  fileIds?: Array<string | number> | null | undefined;
  instrumentIds?: Array<string | number> | null | undefined;
  /** Defaults to 12, at most the settings' longest. */
  months?: number | null | undefined;
  name: string;
  /** With instrumentIds: shares those instruments' parts across the spex' arrangements, including parts added later. */
  spexId?: string | number | null | undefined;
  /** With spexId: only parts in these transpositions. */
  transpositions?: Array<Pitch> | null | undefined;
  versionIds?: Array<string | number> | null | undefined;
};

export type ShareLinkStatus =
  | 'EXPIRED'
  | 'REVOKED'
  | 'VALID';

export type SpexFilter = {
  categoryId?: string | number | null | undefined;
  /** Text the title contains, or the year. */
  q?: string | null | undefined;
  /** Only spex (and their revivals) with material the caller sees. */
  withMaterial?: boolean | null | undefined;
  year?: number | null | undefined;
};

/** A key's tonic as the arranger spelled it, in ASCII: C_SHARP is C♯, B_FLAT is B♭ (Swedish B), B is Swedish H. */
export type Tonic =
  | 'A'
  | 'A_FLAT'
  | 'A_SHARP'
  | 'B'
  | 'B_FLAT'
  | 'C'
  | 'C_SHARP'
  | 'D'
  | 'D_FLAT'
  | 'D_SHARP'
  | 'E'
  | 'E_FLAT'
  | 'F'
  | 'F_SHARP'
  | 'G'
  | 'G_FLAT'
  | 'G_SHARP';

export type TranspositionInput = {
  /** -1, 0 or 1. */
  octave?: number;
  pitch: Pitch;
};

export type VersionInput = {
  arranger?: string | null | undefined;
  /** yyyy-mm-dd */
  date?: string | null | undefined;
  duration?: string | null | undefined;
  /** Replaces the instrumentation when given; arrangements only. */
  instrumentation?: Array<InstrumentationInput> | null | undefined;
  /** Arrangements only. */
  key?: KeyInput | null | undefined;
  label: string;
  /** Replaces the modulations when given; arrangements only. */
  modulations?: Array<KeyInput> | null | undefined;
  notes?: string | null | undefined;
  /** Changes whether the version is restricted when given. */
  restricted?: boolean | null | undefined;
  tempo?: string | null | undefined;
  usedInSpexId?: string | number | null | undefined;
};

